"""Demo: the Fibonacci separation in the simulation preorder."""
from __future__ import annotations
from typing import Callable, Optional


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def poly_bounded_witness(f: Callable[[int], int], max_k: int = 10,
                         n_max: int = 60) -> Optional[int]:
    """Smallest k with f(n)+1 <= (n+2)^k for n<=n_max, else None (super-poly)."""
    for k in range(max_k + 1):
        if all(f(n) + 1 <= (n + 2) ** k for n in range(n_max + 1)):
            return k
    return None


if __name__ == "__main__":
    print("PolyBounded(id) exponent:", poly_bounded_witness(lambda n: n))
    print("PolyBounded(F)  exponent:", poly_bounded_witness(fib), "(None => not bounded)")
    for n in (10, 20, 30, 40):
        print(f"n={n}: (n+2)^4={(n+2)**4}  F(n)={fib(n)}")
    print("=> fibSystem does NOT p-simulate linSystem (Thm 4.6).")

"""Demo: density of the power-tower ladder (Thm 7.5)."""
from __future__ import annotations
from typing import Callable, Optional


def dominates(a: Callable[[int], int], b: Callable[[int], int],
              max_k: int = 8, n_max: int = 40) -> Optional[int]:
    """Smallest k with a(n) <= (b(n)+2)^k for all n<=n_max, else None."""
    for k in range(max_k + 1):
        if all(a(n) <= (b(n) + 2) ** k for n in range(n_max + 1)):
            return k
    return None


def pow_size(k: int) -> Callable[[int], int]:
    return lambda n: 2 ** (n ** k)


def inter_size(k: int) -> Callable[[int], int]:
    return lambda n: 2 ** (n ** (k + 1)) if n % 2 == 0 else 2 ** (n ** k)


if __name__ == "__main__":
    k = 1
    lo, hi, mid = pow_size(k), pow_size(k + 1), inter_size(k)
    print("lo <= mid:", dominates(lo, mid), "  mid <= lo:", dominates(mid, lo))
    print("mid <= hi:", dominates(mid, hi), "  hi <= mid:", dominates(hi, mid))
    print("=> powSystem 1 < interPowSys 1 < powSystem 2.")

"""Demo: holographic proof metric and chain exactness (Thms 8.6-8.9)."""
from __future__ import annotations
from collections import deque
from typing import Callable, List, Optional, Tuple


def min_deriv_len(step: Callable[[int], List[int]], a: int, b: int,
                  bound: int = 10000) -> Optional[int]:
    """Shortest derivation length (graph distance) from a to b via BFS."""
    if a == b:
        return 0
    seen = {a}
    q: deque[Tuple[int, int]] = deque([(a, 0)])
    while q:
        node, d = q.popleft()
        if d > bound:
            return None
        for nxt in step(node):
            if nxt == b:
                return d + 1
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, d + 1))
    return None


def chain_step(n: int) -> List[int]:
    return [n + 1]


if __name__ == "__main__":
    for a, b in [(0, 5), (3, 10)]:
        print(f"minDerivLen({a},{b}) =", min_deriv_len(chain_step, a, b), "= b-a")
    for a, b in [(0, 5), (2, 6)]:
        lo = min_deriv_len(chain_step, a, b)
        hi = min_deriv_len(chain_step, 2 * a, 2 * b)
        print(f"d(2*{a},2*{b})={hi} = 2*{lo}  (stretch-2 doubling: exact, Thm 8.9)")

